import sys
from typing import List
sys.setrecursionlimit(10 ** 8)

class Solution:

	def countDistinctIslands(self, grid: List[List[int]]) -> int:
		m = len(grid)
		n = len(grid[0])
		vis = []
		res = set()
		for i in range(m):
			vis.append([False] * n)
		for i in range(m):
			for j in range(n):
				if grid[i][j] == 1 and vis[i][j] == False:
					l = []
					self.dfs(i, j, grid, vis, l, i, j)
					res.add(str(l))
		return len(res)

	def dfs(self, i, j, grid, vis, l, row0, col0):
		m = len(grid)
		n = len(grid[0])
		if i - 1 >= 0 and j >= 0 and (grid[i - 1][j] == 1) and (vis[i - 1][j] == False):
			vis[i - 1][j] = True
			l.append([i - 1 - row0, j - col0])
			self.dfs(i - 1, j, grid, vis, l, row0, col0)
		if i >= 0 and j - 1 >= 0 and (grid[i][j - 1] == 1) and (vis[i][j - 1] == False):
			vis[i][j - 1] = True
			l.append([i - row0, j - 1 - col0])
			self.dfs(i, j - 1, grid, vis, l, row0, col0)
		if i + 1 <= m - 1 and j <= n - 1 and (grid[i + 1][j] == 1) and (vis[i + 1][j] == False):
			vis[i + 1][j] = True
			l.append([i + 1 - row0, j - col0])
			self.dfs(i + 1, j, grid, vis, l, row0, col0)
		if i <= m - 1 and j + 1 <= n - 1 and (grid[i][j + 1] == 1) and (vis[i][j + 1] == False):
			vis[i][j + 1] = True
			l.append([i - row0, j + 1 - col0])
			self.dfs(i, j + 1, grid, vis, l, row0, col0)
